  function coreCards(list){return [...(list?.cards||[])].sort((a,b)=>b.qty-a.qty).slice(0,6).map(row=>cardName(cardMap.get(row.code))||row.name).join(' / ')}
  function deckListIntel(list){
    const rows=(list?.cards||[]).map(row=>({...row,qty:Number(row.qty)||0,card:cardMap.get(row.code)})),total=rows.reduce((sum,row)=>sum+row.qty,0),known=rows.filter(row=>row.card);
    const costCopies=known.filter(row=>Number.isFinite(Number(row.card.cost))),costTotal=costCopies.reduce((sum,row)=>sum+Number(row.card.cost)*row.qty,0),costCount=costCopies.reduce((sum,row)=>sum+row.qty,0);
    const curve=[0,0,0];costCopies.forEach(row=>{const cost=Number(row.card.cost);curve[cost<=3?0:cost<=6?1:2]+=row.qty});
    const counter=known.filter(row=>Number(String(row.card.counter).replace(/\D/g,''))>0).reduce((sum,row)=>sum+row.qty,0),trigger=known.filter(row=>String(row.card.trigger||row.card.trigger_ja||'').trim()).reduce((sum,row)=>sum+row.qty,0);
    const counterCopies={1000:0,2000:0},characterCosts=Array(11).fill(0);let events=0;
    known.forEach(row=>{const category=String(row.card.category||row.category||'').toLowerCase(),counterValue=Number(String(row.card.counter||'').replace(/\D/g,''));if(Object.hasOwn(counterCopies,counterValue))counterCopies[counterValue]+=row.qty;if(category==='character'){const cost=Number(row.card.cost);if(Number.isInteger(cost)&&cost>=0&&cost<=10)characterCosts[cost]+=row.qty}else if(category==='event')events+=row.qty});
    const core=[...known].sort((a,b)=>b.qty-a.qty||(Number(b.card.cost)||0)-(Number(a.card.cost)||0)).slice(0,6);
    return{total,average:costCount?costTotal/costCount:0,counter,trigger,curve,core,counterCopies,characterCosts,events};
  }
